//! 🧪️ Actual native compiler caller receives each borrowed field and pays its exact cancellation frontier.
use super::*;
use semio_framework_job::{Generation,OperationId};
use crate::native_caller::NativeFrameRootPolicyV1;
fn clock()->Option<u64>{Some(1)}
fn caller()->NativeFrameCaller{let policy:NativeFrameRootPolicyV1=serde_json::from_str(include_str!("../../../../../../⌨️native-entrypoint/🎟️launch/🔣️.json")).map(|value:serde_json::Value|serde_json::from_value(value["compilerTask"].clone()).unwrap()).unwrap();NativeFrameCaller::new(OperationId(731),Generation(2),clock,policy).unwrap()}
fn law()->&'static serde_json::Value{static LAW:std::sync::OnceLock<serde_json::Value>=std::sync::OnceLock::new();LAW.get_or_init(||serde_json::from_str(include_str!("../🔣️.json")).unwrap())}
fn input()->CreateAppBorrowed<'static>{let fields=&law()["fields"];CreateAppBorrowed{path:Path::new(fields[0].as_str().unwrap()),plugin:fields[1].as_str().unwrap(),app:fields[2].as_str().unwrap(),schema:fields[3].as_str().unwrap()}}
fn admit(node:&mut Node,slot:&Slot){for _ in 0..64{if node.caller.ready(){return}node.pump(slot);}panic!("native compiler source did not admit its actual roots")}
#[test]
fn renderer_create_app_source_pays_actual_field_capacity_before_original_source_close(){
 for cut in law()["cancellationCuts"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap() as usize){let slot=Slot::empty();let mut node=Node::new(caller());admit(&mut node,&slot);let mut allocated=0;for _ in 0..cut{let before=node.caller.retained_spent();let (_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||node.receive(&slot,input()));let after=node.caller.retained_spent();assert!(!node.failed);assert_eq!(heap.requested_bytes,after.retained_capacity_bytes-before.retained_capacity_bytes);assert_eq!(heap.released_bytes,0);allocated+=heap.requested_bytes;}
  if cut==4{let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||node.receive(&slot,input()));assert!(slot.published.load(Ordering::Acquire));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let fields=unsafe{&*slot.fields.get()};assert_eq!(fields.path.as_deref(),Some(input().path));assert_eq!(fields.plugin.as_deref(),Some(input().plugin));assert_eq!(fields.app.as_deref(),Some(input().app));assert_eq!(fields.schema.as_deref(),Some(input().schema));}
  slot.detached.store(true,Ordering::Release);let before=node.caller.retained_spent();let mut released=0;for _ in 0..128{if node.closed{break}let before=node.caller.retained_spent();let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||node.pump(&slot));let after=node.caller.retained_spent();assert_eq!(heap.requested_bytes,after.retained_capacity_bytes-before.retained_capacity_bytes);assert_eq!(heap.released_bytes,after.released_bytes-before.released_bytes);released+=heap.released_bytes;}assert!(node.closed);assert!(unsafe{(&*slot.fields.get()).empty_owner()});assert!(node.caller.retained_spent().released_bytes-before.released_bytes>=allocated);assert!(released>=allocated);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(node));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 }println!("[DEBUG] actual native compiler caller field cuts0..4 retain exact path and UTF8 fields; each real allocation/release equals its original receipt, source closes last, terminal Drop0");
}
#[test]
fn renderer_create_app_source_waits_for_actual_task_loan_before_field_retirement(){
 let slot=Slot::empty();let mut node=Node::new(caller());admit(&mut node,&slot);for _ in 0..5{node.receive(&slot,input());}assert!(slot.published.load(Ordering::Acquire));let mut loan=None;let call=node.caller.dispatch_step(|cx|{loan=cx.original_source_parent()?.admit_loan(cx)?;Ok(loan.is_some())});assert_eq!(node.accept(call),Some(true));let binding=node.caller.original_clock_binding();let mut foreign=Node::new(caller());let foreign_slot=Slot::empty();admit(&mut foreign,&foreign_slot);assert_ne!(binding,foreign.caller.original_clock_binding());let call=foreign.caller.dispatch_step(|cx|Ok(loan.as_ref().unwrap().validate_context(cx).is_err()));assert_eq!(foreign.accept(call),Some(true));slot.detached.store(true,Ordering::Release);let before=node.caller.retained_spent();let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{for _ in 0..4{node.pump(&slot);}});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(node.caller.retained_spent(),before);assert_eq!(unsafe{(&*slot.fields.get()).path.as_deref()},Some(input().path));let call=node.caller.dispatch_cleanup_step(|cx|loan.as_mut().unwrap().close_step(cx.original_source_parent()?,cx));assert!(node.accept(call).is_some());assert!(loan.as_ref().unwrap().terminal_is_empty());loan.take();for _ in 0..128{if node.closed{break}node.pump(&slot);}assert!(node.closed);foreign_slot.detached.store(true,Ordering::Release);for _ in 0..128{if foreign.closed{break}foreign.pump(&foreign_slot);}assert!(foreign.closed);println!("[DEBUG] actual compiler issuer keeps exact fields after primary return until its genuine task loan returns; another identical numeric operation has a different full original clock/source and cannot use that loan");
}
